// @generated by:gauntlet run:godseye-e06-completion
import { ChildProcess } from "node:child_process";
import { randomUUID } from "node:crypto";
import { schema } from "@godseye/store";
import { eq } from "drizzle-orm";
import { afterEach, describe, expect, it } from "vitest";
import { createCellBroker } from "../apps/jobs-runtime/src/broker.js";
import { createRpcPeer } from "../apps/jobs-runtime/src/ipc.js";
import { inputCell } from "./inngest-runtime-fixture.js";
import { deferred, type JobsFixture, jobsFixture } from "./jobs-helpers.js";

describe("connection-bound autonomous cell admission", () => {
  let fixture: JobsFixture | undefined;
  let peer: ReturnType<typeof createRpcPeer> | undefined;
  afterEach(async () => {
    peer?.close();
    peer = undefined;
    await fixture?.store.close();
    fixture = undefined;
  });

  async function setup(
    admission: () => boolean = () => true,
    reply?: (method: string, payload: unknown) => Promise<unknown>,
  ) {
    const active = await jobsFixture();
    fixture = active;
    const configuration = {
      enabled: true,
      registrationEnabled: true,
      allowedOrigins: ["http://localhost:4731"],
      maxFileMiB: 1,
      storageMiB: 16,
      maxFiles: 8,
      eventRetention: 16,
    };
    await active.core.configureBackend(
      { ...active.freshOwner(), authenticatedAt: new Date().toISOString() },
      active.project.id,
      active.development.id,
      {
        expectedRevision: 0,
        expectedProjectRevision: active.project.revision,
        expectedEnvironmentRevision: active.development.revision,
        configuration,
      },
      randomUUID(),
    );
    const cell = {
      ...inputCell(),
      projectId: active.project.id,
      environmentId: active.development.id,
    };
    const broker = createCellBroker(active.store, cell, 1, admission);
    const producerId = randomUUID();
    const remoteCalls: string[] = [];
    let receive: ((message: unknown) => void) | undefined;
    peer = createRpcPeer(
      {
        send(raw) {
          if (!raw || typeof raw !== "object" || !("method" in raw) || !("id" in raw)) return;
          remoteCalls.push(String(raw.method));
          queueMicrotask(async () =>
            receive?.({
              kind: "response",
              id: raw.id,
              ok: true,
              result: reply
                ? await reply(String(raw.method), "payload" in raw ? raw.payload : null)
                : { status: "succeeded", evidenceRef: "remote:done" },
            }),
          );
        },
        subscribe(listener) {
          receive = listener;
          return () => {
            receive = undefined;
          };
        },
        closed() {
          return () => undefined;
        },
      },
      { onRequest: async () => null },
    );
    broker.bind(active.infrastructure, {
      peer,
      child: new ChildProcess(),
      producerId,
      handlers: ["fixture.work"],
      senders: [],
      close: async () => undefined,
    });
    const envelope = {
      id: randomUUID(),
      projectId: cell.projectId,
      environmentId: cell.environmentId,
      producerId,
      epoch: 1,
      eventType: "document.updated",
      userId: "fixture-user",
      payload: { revision: 1 },
      occurredAt: new Date().toISOString(),
    };
    await active.register({ trigger: { kind: "event", eventType: "document.updated" } });
    return { active, broker, envelope, configuration, remoteCalls };
  }

  it("T-E06-D02 a child cannot substitute another project, environment or producer in admission or observations", async () => {
    const { active, broker, envelope } = await setup();
    for (const changed of [
      { projectId: active.secondProject.id },
      { environmentId: active.production.id },
      { producerId: randomUUID() },
    ])
      for (const method of ["ingest", "runs", "accepted", "settled"])
        await expect(broker.onRequest(method, { ...envelope, ...changed })).rejects.toMatchObject({
          code: "FORBIDDEN",
        });

    expect((await active.jobs().overview(active.freshOwner())).runs).toHaveLength(0);
  });

  it("T-E06-D02 exact domain replay deduplicates but changed content cannot replace the accepted event", async () => {
    const { active, broker, envelope } = await setup();
    const first = await broker.onRequest("ingest", envelope);
    const replay = await broker.onRequest("ingest", envelope);

    expect(replay).toEqual(first);
    expect(await broker.onRequest("accepted", envelope)).toBe(true);
    await expect(
      broker.onRequest("ingest", { ...envelope, payload: { revision: 2 } }),
    ).rejects.toMatchObject({ code: "IDEMPOTENCY_CONFLICT" });
    expect((await active.jobs().overview(active.freshOwner())).runs).toHaveLength(1);
  });

  it("T-E06-D02 unsupported methods and caller-selected outbox authority cannot use the owner journal", async () => {
    const { broker } = await setup();
    for (const method of ["owner.approve", "db.query", "list-projects", "shutdown"])
      await expect(broker.onRequest(method, null)).rejects.toMatchObject({
        code: "METHOD_NOT_ALLOWED",
      });
    await expect(
      broker.onRequest("outbox", {
        attemptKey: "unowned-attempt",
        intent: { effectKey: "fixture-unowned", destination: "fixture.sink", payload: {} },
      }),
    ).rejects.toMatchObject({ code: "FENCED" });
    await expect(
      broker.onRequest("outbox", {
        attemptKey: "unowned-attempt",
        projectId: randomUUID(),
        intent: { effectKey: "fixture-unowned", destination: "fixture.sink", payload: {} },
      }),
    ).rejects.toBeInstanceOf(Error);
  });

  it("T-E06-D04 a current recovery HOLD parks child admission while retaining previously accepted intent", async () => {
    const { active, broker, envelope } = await setup();
    await broker.onRequest("ingest", envelope);
    await active.store.db
      .update(schema.environments)
      .set({ recoveryHold: true })
      .where(eq(schema.environments.id, active.development.id));

    expect(await broker.onRequest("lifecycle", null)).toMatchObject({ available: false, epoch: 1 });
    await expect(
      broker.onRequest("ingest", { ...envelope, id: randomUUID() }),
    ).rejects.toMatchObject({ code: "FENCED" });
    expect(await broker.onRequest("accepted", envelope)).toBe(true);
    expect((await active.jobs().overview(active.freshOwner())).runs).toHaveLength(1);
    expect(active.handler.calls).toHaveLength(0);
  });

  it.each(["manual", "cron"] as const)(
    "T-E06-D04 a %s job fenced after context loading cannot invoke the physical child handler",
    async (trigger) => {
      const { active, broker, remoteCalls } = await setup();
      const definition = await active.register({
        name: `late-${trigger}`,
        trigger: trigger === "manual" ? { kind: "manual" } : { kind: "cron", cron: "*/5 * * * *" },
        effectPolicy: "protected",
        limits: { maxConcurrent: 1, maxAttempts: 1, timeoutSeconds: 30, retentionDays: 7 },
      });
      active.handler.script = async (context) => {
        await active.infrastructure.foundation.advanceEpoch(
          active.freshOwner(),
          active.development.id,
          randomUUID(),
        );
        return broker.execute(context);
      };
      if (trigger === "manual")
        await active.trigger(definition.id, definition.revision, `late-${trigger}-run`);
      else active.clock.advance(5 * 60_000);

      await active.work();

      expect(remoteCalls.includes("execute")).toBe(false);
      const runs = (await active.jobs().overview(active.freshOwner())).runs;
      expect(runs).toHaveLength(1);
      expect(runs[0]).toMatchObject({ definitionId: definition.id, state: "unknown" });
    },
  );

  it("T-E06-D04 loses dispatch authority while a lease check is pending and never invokes the physical child", async () => {
    let allowed = true;
    const { active, broker, remoteCalls } = await setup(() => allowed);
    const entered = deferred(),
      release = deferred();
    const definition = await active.register({
      name: "admission-loss",
      effectPolicy: "protected",
      limits: { maxConcurrent: 1, maxAttempts: 1, timeoutSeconds: 30, retentionDays: 7 },
    });
    active.handler.script = (context) =>
      broker.execute({
        ...context,
        assertActive: async () => {
          entered.resolve();
          await release.promise;
          await context.assertActive();
        },
      });
    await active.trigger(definition.id, definition.revision, "admission-loss-while-checking");
    const work = active.work();
    await entered.promise;
    allowed = false;
    release.resolve();

    await work;

    expect(remoteCalls.includes("execute")).toBe(false);
    expect((await active.jobs().overview(active.freshOwner())).runs[0]?.state).toBe("unknown");
  });

  it("T-E06-D04 fences a read-only probe whose epoch changes after its context is loaded", async () => {
    const { active, broker, remoteCalls } = await setup();
    const definition = await active.register({
      name: "late-readonly-probe",
      effectPolicy: "protected",
      limits: { maxConcurrent: 1, maxAttempts: 1, timeoutSeconds: 30, retentionDays: 7 },
    });
    active.handler.script = async () => ({ status: "unknown" });
    const run = await active.trigger(definition.id, definition.revision, "late-readonly-probe-run");
    await active.work();
    active.handler.probe = async (context) => {
      await active.infrastructure.foundation.advanceEpoch(
        active.freshOwner(),
        active.development.id,
        randomUUID(),
      );
      return broker.execute(context, true);
    };

    await expect(
      active.jobs().reconcileRun(
        active.freshOwner(),
        run.id,
        {
          expectedState: "unknown",
          resolution: "probe_read_only",
          evidenceRef: "fixture:late-readonly-probe",
        },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ code: "FENCED" });

    expect(remoteCalls.includes("execute")).toBe(false);
    expect((await active.state(run.id)).state).toBe("unknown");
  });

  it("T-E06-D04 outbox authorization loses admission during awaited lifecycle I/O and cannot authorize delivery", async () => {
    let allowed = true;
    const observed = deferred<string>(),
      result = deferred<unknown>();
    const { active, broker } = await setup(
      () => allowed,
      async (method, payload) => {
        if (
          method === "deliver-outbox" &&
          payload &&
          typeof payload === "object" &&
          "callId" in payload
        ) {
          observed.resolve(String(payload.callId));
          return result.promise;
        }
        return null;
      },
    );
    const intent = active.intent("admission-loss-outbox", { revision: 1 });
    const row = await active.jobs().transact((tx) => active.jobs().enqueueOutbox(tx, intent));
    await active.store.db
      .update(schema.jobOutbox)
      .set({ state: "dispatching", attempts: 1 })
      .where(eq(schema.jobOutbox.id, row.id));
    const dispatched = broker.outbox({ ...intent, attempt: 1 }, false);
    const callId = await observed.promise;
    const entered = deferred(),
      release = deferred();
    const original = active.store.transaction.bind(active.store);
    active.store.transaction = async (work) => {
      entered.resolve();
      await release.promise;
      return original(work);
    };
    const authorization = broker.onRequest("authorize-outbox", callId);
    const refused = expect(authorization).rejects.toMatchObject({ code: "FENCED" });
    await entered.promise;
    allowed = false;
    release.resolve();

    await refused;
    active.store.transaction = original;
    result.resolve({ status: "unknown" });
    expect(await dispatched).toEqual({ status: "unknown" });
    expect((await active.outboxRows())[0]?.state).toBe("dispatching");
  });
});
